const repo = new Map();                       // component repository

export async function link(name, specifier) { // configurator
  const mod = await import(specifier);
  const factory = mod.create ?? mod.default;
  if (typeof factory !== "function") throw new Error(`${name}: not a component`);
  repo.set(name, factory());
}
export function unlink(name) { repo.delete(name); }  // code itself stays loaded
